import {clamp,ease,stageAt} from './svg.js';
export const topic={number:'06',title:'BGA 焊點熱循環疲勞',question:'回到同一溫度，焊點也回到原來的健康狀態嗎？',duration:34,overview:28,simplification:'選用SAC305板級BGA代表剖面。上封裝與下電路板以共同中心對稱伸縮；本例電路板的有效膨脹較大，外側焊點受較明顯相對位移。形變、裂紋及循環時間放大，只用室溫／熱端／冷端示意，所有溫度低於焊料熔點，不提供壽命或循環數預測。封裝側裂紋參考UMD研究案例，不宣稱所有封裝都在相同位置失效。放大窗是右側同一焊點的同步資訊副本。',supplement:'<p>疲勞也受錫晶粒取向、微結構、接點幾何及界面影響。這裡僅追蹤一個外側接點的代表裂紋；沒有把電遷移、吸濕、跌落或熔化混入機制。部分裂紋仍保留金屬通路，不直接宣告斷路。</p>',sources:[{title:'Sandia · Solder Joint Reliability, Part 2 (2017)',url:'https://www.sandia.gov/research/publications/details/understanding-the-reliability-of-solder-joints-used-in-advanced-structural-2017-03-01/',claim:'原始報告摘要：材料熱膨脹差與熱機械疲勞。'},{title:'University of Maryland · Thermal Cycling Reliability (2010)',url:'https://drum.lib.umd.edu/items/d9fc3168-3bdf-4bc2-b5f8-511e9b5b8a4f',claim:'原研究摘要支持SAC305板級接點及封裝側失效；未完整讀取大型PDF，不採用未核對的幾何或循環數。'},{title:'Xian et al. · Microstructure in Thermal Fatigue',url:'https://arxiv.org/abs/2311.03891',claim:'作者原稿摘要：SAC305 BGA的晶粒取向與陣列位置影響損傷。'}]};
export const stages=[{start:0,key:3,title:'室溫與共同中心',explain:'上方封裝、下方電路板及七個代表焊點保持連接。虛線標出共同中心。',detail:'橙框追蹤最右側同一焊點；放大窗是它的資訊副本，不是額外試件。'},{start:5,key:8,title:'升至熱端，相對剪切',explain:'上下材料都從中心向外膨脹，但幅度不同；外側焊點的上、下端相對錯開。',detail:'焊料保持固態。移動量為放大示意，並不是熔化流動。'},{start:10,key:11,title:'冷端回縮，剪切換向',explain:'材料收縮，外側接點的相對位移換向。共同中心不隨整個裝置平移。',detail:'第一組熱冷變化先建立形變觀察，後續縮時循環再呈現損傷。'},{start:14,key:19,title:'反覆熱冷，裂紋累積',explain:'經過更多代表循環，封裝側附近裂紋從外側邊緣向內成長。',detail:'裂紋不因下一次升溫或降溫而縮短。這些快速循環不能換算真實壽命。'},{start:26,key:28,title:'回到室溫，裂紋仍在',explain:'上下材料回到室溫幾何，裂紋卻保留，接點健康狀態已改變。',detail:'裂紋尚未完全貫穿，仍有連續金屬通路；此處稱為退化。'},{start:29,key:32,title:'受損件退場，換新試件',explain:'帶裂紋的封裝與電路板一起移出，新的完整接點組另外進場。',detail:'新循環不把同一試件的裂紋倒轉癒合。'}];
export function temperature(t){const knots=[[0,0],[5,0],[8,1],[11,-1],[14,1],[17,-1],[20,1],[23,-1],[26,0],[34,0]];for(let i=1;i<knots.length;i++)if(t<=knots[i][0]){const[a,x]=knots[i-1],[b,y]=knots[i];return x+(y-x)*ease((t-a)/(b-a));}return 0;}
export function stateAt(t){const index=stageAt(t,stages),temp=temperature(t);return{t,index,title:stages[index].title,temp,damage:clamp((t-14)/12),thermal:Math.abs(temp)<.12?'室溫附近':temp>0?'熱端方向':'冷端方向',caption:t<5?'共同中心 · 固態 SAC305':t<14?'上下膨脹差 → 外側相對剪切':t<26?'縮時熱冷循環 · 裂紋逐步累積':t<29?'同一室溫 · 損傷沒有回復':'受損試件與新試件分別進出'};}
